import torch

# Load the dataset to understand its structure
dataset = torch.load('/app/dataset.pt')
print("Dataset type:", type(dataset))
if isinstance(dataset, dict):
    print("Dataset keys:", dataset.keys())
    for key in dataset:
        print(f"  {key}: {dataset[key].shape if hasattr(dataset[key], 'shape') else type(dataset[key])}")
elif isinstance(dataset, (list, tuple)):
    print(f"Dataset length: {len(dataset)}")
    for i, item in enumerate(dataset[:2]):
        if isinstance(item, torch.Tensor):
            print(f"  Item {i}: {item.shape}")
        elif isinstance(item, tuple):
            print(f"  Item {i} (tuple): {[x.shape if isinstance(x, torch.Tensor) else type(x) for x in item]}")
